// justrealmilk/destiny-icons, licence CC0). Identifiées via des MOTS-CLÉS dans le texte réel de
// Bungie (piece.typeArme / r.typeArme), pas une correspondance exacte -
// plus robuste face aux variations de formulation.
// EN: weapon type icons, provided by the user (source justrealmilk/destiny-icons, licence CC0).
// Identified via KEYWORDS in Bungie's real text (piece.typeArme /
// r.typeArme), not an exact match - more robust against wording
// variations.

interface Props {
  typeArme: string | undefined;
  /** FR : nécessaire pour distinguer les 2 variantes de Lance-grenades (spécial=energie vs lourd=lourde), le texte étant identique pour les deux. / EN: needed to distinguish the 2 Grenade Launcher variants (special=energy vs heavy=heavy), the text being identical for both. */
  slot?: string;
  /** FR : ⚠️ AJOUT (01/10/2026) - type de munitions de l'arme, s'il est connu : distingue les deux lance-grenades (prioritaire sur `slot`). / EN: ⚠️ ADDED - the weapon's ammo type, if known: tells the two grenade launchers apart (takes precedence over `slot`). */
  munition?: TypeMunition;
  /** FR : ⚠️ AJOUT (02/10/2026) - catégories d'objet du Manifest : repli quand le texte du type est vide ou non reconnu (ex. « Lance de Polaris »). / EN: ⚠️ ADDED - Manifest item categories: fallback when the type text is empty or unrecognised. */
  categories?: number[];
  /** FR : ⚠️ AJOUT (05/10/2026) - libellé de type de dernier recours (lib/manifest/typeArmeSecours.ts), essayé après le texte et les catégories. / EN: ⚠️ ADDED - last-resort type label, tried after text and categories. */
  typeSecours?: string;
  /** FR : ⚠️ AJOUT (05/10/2026) - description technique de l'objet, ajoutée au badge de diagnostic quand aucune icône n'est trouvée. / EN: ⚠️ ADDED - technical description of the item, appended to the diagnostic badge. */
  infoObjet?: string;
  taille?: number;
  couleur?: string;
}

// FR : ⚠️ AJOUT (01/10/2026) - type seulement (aucune dépendance à l'exécution) : le type de munitions
// qui départage les deux lance-grenades. / EN: type only: the ammo type telling the two grenade launchers apart.
import type { TypeMunition } from "./IconeMunition";
import { normaliserRecherche } from "../../lib/manifest/search";

// FR : ⚠️ CHANGÉ (23/10/2026, audit) - `normaliser` local supprimé : remplacé par la version enrichie de `search.ts` (même base NFD + minuscules, PLUS tolérance aux espaces insécables, apostrophes typographiques, césures/zero-width). Aucun effet sur les types déjà reconnus (aucun mot-clé ne contient ces caractères).
// EN: ⚠️ CHANGED - local `normaliser` removed: replaced by the enriched version from `search.ts` (same NFD + lowercase base, PLUS tolerance to nbsp, typographic apostrophes, soft hyphens/zero-width). No effect on already-recognised types (no keyword contains those characters).

// FR : ⚠️ AJOUT (04/08/2026) - certaines icônes ont un viewBox très
// allongé (Glaive, Lance-roquettes, Fusil à fusion linéaire - des formes
// naturellement fines), ce qui les faisait paraître bien plus petites
// que les autres une fois forcées dans un carré fixe (largeur/hauteur
// identiques). On calcule maintenant la taille de rendu à partir du
// VRAI ratio largeur/hauteur du viewBox, pour que la plus grande
// dimension de chaque icône corresponde toujours à `taille` - même
// poids visuel pour toutes, forme allongée ou non.
// EN: ⚠️ ADDED (2026-08-04) - some icons have a very elongated viewBox
// (Glaive, Rocket Launcher, Linear Fusion Rifle - naturally thin shapes),
// which made them look much smaller than others once forced into a
// fixed square (identical width/height). Render size is now computed
// from the viewBox's REAL width/height ratio, so each icon's largest
// dimension always matches `taille` - equal visual weight for all,
// elongated shape or not.
export function calculerTailleRendu(viewBox: string, taille: number): { largeur: number; hauteur: number } {
  const parties = viewBox.split(" ").map(Number);
  const [, , largeurVb, hauteurVb] = parties;
  if (!largeurVb || !hauteurVb) return { largeur: taille, hauteur: taille };
  const ratio = largeurVb / hauteurVb;
  if (ratio >= 1) return { largeur: taille, hauteur: taille / ratio };
  return { largeur: taille * ratio, hauteur: taille };
}

