export function trouverFormeTypeArme(
  typeArme: string | undefined,
  slot?: string,
  munition?: TypeMunition,
  // FR : ⚠️ AJOUT (02/10/2026) - catégories d'objet du Manifest (`obtenirCategoriesObjet`), s'il est
  // chargé. Utilisées SEULEMENT si le texte du type est vide ou non reconnu : un texte reconnu garde
  // toujours la priorité (aucun type d'arme actuellement reconnu ne change).
  // EN: ⚠️ ADDED - Manifest item categories, used ONLY if the type text is empty or unrecognised.
  categories?: number[],
  // FR : ⚠️ AJOUT (05/10/2026) - libellé de type de DERNIER RECOURS (voir `obtenirSecoursTypeArme`, lib/manifest/typeArmeSecours.ts),
  // essayé seulement si le texte ET les catégories n'ont rien donné. Cas : une deuxième « Lance de Polaris », dont la définition n'a
  // aucun texte de type et pour seule catégorie le numéro 3109687656, alors que l'autre exemplaire s'affichait correctement.
  // EN: ⚠️ ADDED - last-resort type label, tried only when text AND categories gave nothing.
  typeSecours?: string
): { viewBox: string; d: string } | undefined {
  const direct = formeDepuisTexte(typeArme, slot, munition);
  if (direct) return direct;
  if (categories && categories.length > 0) {
    const ensemble = new Set(categories);
    const trouve = CATEGORIES_TYPE_ARME.find(([hash]) => ensemble.has(hash));
    const parCategorie = trouve ? formeDepuisTexte(trouve[1], slot, munition) : undefined;
    if (parCategorie) return parCategorie;
  }
  return typeSecours ? formeDepuisTexte(typeSecours, slot, munition) : undefined;
}

/** FR : ⚠️ AJOUT (05/10/2026) - ce texte de type est-il reconnu comme un type d'arme ? / EN: is this type text recognised as a weapon type? */
export function typeArmeReconnu(texte: string | undefined): boolean {
  return formeDepuisTexte(texte) !== undefined;
}

/** FR : ⚠️ AJOUT (05/10/2026) - libellé français déduit des catégories d'objet du Manifest, ou undefined. / EN: French label derived from item categories, or undefined. */
export function libelleDepuisCategories(categories: readonly number[] | undefined): string | undefined {
  if (!categories || categories.length === 0) return undefined;
  const ensemble = new Set(categories);
  return CATEGORIES_TYPE_ARME.find(([hash]) => ensemble.has(hash))?.[1];
}

// FR : badge de diagnostic survolable, affiché à la place d'une icône
// quand on ne sait pas quoi afficher. Même gabarit que les icônes pour
// garder les lignes alignées, et cible de survol assez large pour ne pas
// déclencher l'infobulle de l'arme à la place.
// EN: hoverable diagnostic badge, shown instead of an icon when we don't
// know what to display. Same footprint as the icons to keep rows aligned,
// with a hover target large enough not to trigger the weapon's tooltip.
function BadgeDiagnostic({ texte, taille }: { texte: string; taille: number }) {
  return (
    <span
      title={texte}
      style={{
        display: "inline-flex",
        alignItems: "center",
        justifyContent: "center",
        width: taille,
        height: taille,
        fontSize: Math.max(10, taille * 0.5),
        color: "#5a5f6b",
        border: "1px solid #3a3f4b",
        borderRadius: 4,
        cursor: "help",
        flexShrink: 0,
      }}
    >
      ?
    </span>
  );
}

export default function IconeTypeArme({ typeArme, slot, munition, categories, typeSecours, infoObjet, taille = 16, couleur = "#b7b3a8" }: Props) {
  // FR : ⚠️ CORRIGÉ (04/08/2026) - ne renvoie PLUS JAMAIS null en
  // silence. C'est la cause la plus probable des armes signalées sans
  // icône NI badge de diagnostic ("Diseur de vérité", "Trame de
  // machin") : `typeArme` vaut undefined ou "" pour ces objets, et
  // l'ancien `if (!typeArme) return null` les faisait disparaître sans
  // laisser la moindre trace à diagnostiquer. Le badge s'affiche
  // désormais dans TOUS les cas non résolus, en indiquant précisément
  // ce qui manque.
  // EN: ⚠️ FIXED (2026-08-04) - NEVER silently returns null anymore.
  // This is the most likely cause of the weapons reported with neither
  // icon NOR diagnostic badge: `typeArme` is undefined or "" for those
  // items, and the old `if (!typeArme) return null` made them vanish
  // without leaving anything to diagnose. The badge now shows in ALL
  // unresolved cases, stating precisely what's missing.
  // FR : ⚠️ CHANGÉ (02/10/2026) - on tente d'abord la reconnaissance (texte, puis catégories du
  // Manifest en repli) ; le badge de diagnostic n'apparaît que si rien n'aboutit, et indique alors
  // aussi les catégories de l'objet, pour comprendre le cas sans deviner.
  // EN: ⚠️ CHANGED - recognition first (text, then Manifest categories as fallback); the diagnostic
  // badge only shows if nothing works, and now also states the item's categories.
  const infoCategories = (categories && categories.length > 0 ? ` ; catégories du Manifest : ${categories.join(", ")}` : "") + (infoObjet ? ` ; ${infoObjet}` : "");
  const trouve = trouverFormeTypeArme(typeArme, slot, munition, categories, typeSecours);
  if (!trouve) {
    if (!typeArme || !typeArme.trim()) {
      return (
        <BadgeDiagnostic
          taille={taille}
          texte={`Type d'arme absent du Manifest pour cet objet (emplacement : ${slot ?? "inconnu"})${infoCategories}`}
        />
      );
    }
    // FR : ⚠️ AJOUT (04/08/2026) - petit indicateur discret et survolable
    // (au lieu de rien) quand aucun mot-clé ne correspond, montrant le
    // texte BRUT du type - permet de comprendre en un coup d'œil pourquoi
    // une icône manque (type pas encore couvert, ou texte inattendu),
    // sans deviner à l'aveugle.
    // EN: ⚠️ ADDED (2026-08-04) - small discreet, hoverable indicator
    // (instead of nothing) when no keyword matches, showing the RAW type
    // text - lets us understand at a glance why an icon is missing (type
    // not covered yet, or unexpected text), without guessing blindly.
    //
    // FR : ⚠️ CORRIGÉ (04/08/2026) - agrandi et transformé en badge avec
    // bordure (au lieu d'un simple "·" minuscule) - trop petit pour être
    // survolé précisément, ce qui faisait apparaître l'infobulle de
    // l'arme entière à la place (signalé sur "Vigile Liminaire").
    // Factorisé dans BadgeDiagnostic, et l'emplacement est maintenant
    // inclus dans le texte : le type seul ne suffisait pas à comprendre
    // les cas ambigus.
    // EN: ⚠️ FIXED (2026-08-04) - enlarged into a bordered badge (instead
    // of a tiny "·") - too small to hover precisely, causing the whole
    // weapon's tooltip to show instead (reported on "Vigile Liminaire").
    // Factored into BadgeDiagnostic, and the slot is now included in the
    // text: the type alone wasn't enough to understand ambiguous cases.
    return (
      <BadgeDiagnostic taille={taille} texte={`${typeArme} (emplacement : ${slot ?? "inconnu"})${infoCategories}`} />
    );
  }

  const { largeur, hauteur } = calculerTailleRendu(trouve.viewBox, taille);
  return (
    <svg width={largeur} height={hauteur} viewBox={trouve.viewBox} fill={couleur} aria-label={typeArme} style={{ flexShrink: 0 }}>
      <path d={trouve.d} />
    </svg>
  );
}
